import pytest

from bedrock_protocol import v924, v1001, v2168

# generated by gophertunnel 0381a95:
# packet.AnvilDamage{Damage: 3, AnvilPosition: protocol.BlockPos{1, 200, 3}}
V924_HIGH_Y = bytes.fromhex("0302c80106")

# generated by gophertunnel 6353c49:
# packet.AnvilDamage{Damage: 3, AnvilPosition: protocol.BlockPos{1, 200, 3}}
V1001_HIGH_Y = bytes.fromhex("0302900306")

# generated by gophertunnel 6353c49:
# packet.AnvilDamage{Damage: 3, AnvilPosition: protocol.BlockPos{1, 2, 3}}
V1001 = bytes.fromhex("03020406")

# generated by gophertunnel b8bd735:
# packet.AnvilDamage{AnvilPosition: protocol.BlockPos{1, 2, 3}}
V2168 = bytes.fromhex("020406")

GOLDENS = [
    pytest.param(
        v924.AnvilDamagePacket(damage=3, position=v924.NetworkBlockPosition(x=1, y=200, z=3)),
        V924_HIGH_Y,
        id="v924-unsigned-y",
    ),
    pytest.param(
        v1001.AnvilDamagePacket(damage=3, position=v1001.BlockPos(x=1, y=200, z=3)),
        V1001_HIGH_Y,
        id="v1001-zigzag-y",
    ),
    pytest.param(
        v1001.AnvilDamagePacket(damage=3, position=v1001.BlockPos(x=1, y=2, z=3)),
        V1001,
        id="v1001",
    ),
    pytest.param(
        v2168.AnvilDamagePacket(position=v2168.BlockPos(x=1, y=2, z=3)),
        V2168,
        id="v2168",
    ),
]


@pytest.mark.parametrize("version", [v924, v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_anvil_damage_is_packet_141(version):
    assert version.PACKETS[141] is version.AnvilDamagePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_anvil_damage_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_anvil_damage_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_same_position_takes_a_different_y_either_side_of_944():
    before = v924.AnvilDamagePacket(damage=3, position=v924.NetworkBlockPosition(x=1, y=200, z=3))
    after = v1001.AnvilDamagePacket(damage=3, position=v1001.BlockPos(x=1, y=200, z=3))
    assert bytes(before) != bytes(after)


def test_a_v1001_anvil_damage_body_does_not_decode_as_a_v2168_one():
    with pytest.raises(ValueError, match="trailing bytes"):
        v2168.AnvilDamagePacket.from_bytes(V1001)


def test_a_v2168_anvil_damage_body_does_not_decode_as_a_v1001_one():
    with pytest.raises(ValueError, match="at byte"):
        v1001.AnvilDamagePacket.from_bytes(V2168)
